<?php declare(strict_types=1);function fh(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function fm(mixed $v):string{return number_format((float)$v,0,',',' ').' FCFA';}?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registre des FEB · FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><style>
.feb-shell{max-width:1420px}.feb-heading{display:flex;align-items:center;justify-content:space-between;gap:22px;margin-bottom:20px;padding:26px 28px;color:#fff;background:linear-gradient(120deg,var(--brand-primary),#3a3e77);border-radius:22px}.feb-heading h1{margin:0!important;color:#fff!important;font-size:1.5rem}.feb-heading p{margin:5px 0 0;color:#ffffffad}.registry{overflow:hidden;background:#fff;border:1px solid var(--brand-border);border-radius:19px;box-shadow:0 10px 30px #22254b0c}.registry-head{display:flex;align-items:center;justify-content:space-between;padding:17px 20px;border-bottom:1px solid var(--brand-border)}.registry-head strong{color:var(--brand-primary)}.feb-table-wrap{overflow-x:auto}.feb-table{width:100%;min-width:1050px;border-collapse:collapse}.feb-table th{padding:11px 13px;color:#777a8d;background:#f7f7fa;font-size:.62rem;text-transform:uppercase}.feb-table td{padding:13px;border-bottom:1px solid #ededf2;font-size:.72rem;white-space:nowrap}.feb-table tr:last-child td{border:0}.doc-id{display:block;color:#858899;font-size:.6rem}.amount{color:var(--brand-primary);font-weight:900;text-align:right}.actions{display:flex;justify-content:flex-end;gap:6px}.empty{padding:55px;text-align:center;color:#858899}@media(max-width:700px){.feb-heading{align-items:flex-start;flex-direction:column}}
</style></head><body class="module-page"><?php include APP_ROOT.'/partials/navbar.php';?><main class="container feb-shell"><header class="feb-heading"><div><h1><i class="fa-solid fa-file-circle-check me-2 text-warning"></i>Registre des FEB</h1><p>Consultez, contrôlez et exportez les fiches d’expression de besoin maîtrisées.</p></div><a class="btn btn-warning" href="suivi_affaires.php"><i class="fa-solid fa-plus me-1"></i>Préparer une FEB</a></header><section class="registry"><div class="registry-head"><strong><?=count($rows)?> fiche<?=count($rows)>1?'s':''?></strong><span class="badge text-bg-light">Documents FIDEST contrôlés</span></div><div class="feb-table-wrap"><table class="feb-table"><thead><tr><th>Document</th><th>Client / affaire</th><th>Commande</th><th>Planning</th><th>Fournitures</th><th>Transport</th><th>Total</th><th>Statut</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=fh($row['numero_feb'])?></strong><small class="doc-id"><?=fh($row['document_uid'])?> · V<?=fh($row['document_version'])?></small></td><td><strong><?=fh($row['nom_client'])?></strong><span class="doc-id"><?=fh($row['num_offre'].' · '.$row['numero_devis'])?></span></td><td><?=fh($row['numero_bc'])?></td><td><?=fh(date('d/m/Y',strtotime($row['date_debut'])))?> → <?=fh(date('d/m/Y',strtotime($row['date_fin'])))?></td><td class="amount"><?=fm($row['montant_fournitures'])?></td><td class="amount"><?=fm($row['montant_transport'])?></td><td class="amount"><?=fm($row['montant_demande'])?></td><td><span class="badge text-bg-<?=$row['statut']==='approuve'?'success':($row['statut']==='rejete'?'danger':'warning')?>"><?=fh($row['statut'])?></span></td><td><div class="actions"><a class="btn btn-sm btn-outline-primary" target="_blank" href="request/export_feb_pdf.php?id=<?=(int)$row['id']?>"><i class="fa-regular fa-eye"></i></a><a class="btn btn-sm btn-primary" href="request/export_feb_pdf.php?id=<?=(int)$row['id']?>&download=1"><i class="fa-solid fa-download"></i> PDF</a></div></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty"><i class="fa-regular fa-folder-open fa-2x d-block mb-2"></i>Aucune FEB préparée.</div><?php endif;?></div></section></main></body></html>
